---@return string | nil  @ 若有效, 返回剔除掉 head_ 后剩余的字符串
function IdolLive3D_UtilsV2.IsKeyStartWith( key_, head_ ) 
    ---@type IdolLive3D_StatesV2
    local IdolLive3D_StatesV2 = import('Game.IdolLive3D.V2.IdolLive3D_StatesV2')
    if string.startsWith(key_, head_) == false then
        return nil
    end 
    local left = string.sub(key_, #head_ + 1) -- 剔除掉头部 head_
    return left
end




function IdolLive3D_UtilsV2.SyncTransform( tf_, posWS_, rotationWS_ ) 
    tf_.position = posWS_
    tf_.rotation = rotationWS_
end



---@return UnityEngine.Vector3 | nil, boolean  @(1) ray 在 椭圆内最近的点 posws; (2) ray 与椭圆平面的交点 是否在 椭圆内部
function IdolLive3D_UtilsV2.FindClosestPosOnEllipse( ellipseTF_, ray_, radiusX_, radiusZ_ )
    -- Step 1:  
    local ellipsePlane = Plane(ellipseTF_.up, ellipseTF_.position) 
    local isHit, enter = ellipsePlane:Raycast(ray_)
    if isHit == false then    
        print("未找到 ray 和 可活动平面的 交点")
        return nil, false  -- !! 鼠标拖动并离开窗口时, 会出现此情况
    end
    local hitPosWS = ray_:GetPoint(enter)  -- ray_ 和椭圆平面的交点
    local hitPosLS = ellipseTF_:InverseTransformPoint(hitPosWS)

    -- Step 2:  
    local x = hitPosLS.x
    local z = hitPosLS.z  
    local ellipseEquation = (x * x) / (radiusX_ * radiusX_) + (z * z) / (radiusZ_ * radiusZ_)

    if ellipseEquation <= 1.0  then  
        return hitPosWS, true
    else    
        local zxRatio = radiusZ_ / radiusX_
        local x2 = x
        local z2 = z / zxRatio
        local nearPosLS = Vector3(x2,0,z2).normalized * radiusX_
        nearPosLS.z = nearPosLS.z * zxRatio
        local nearPosWS = ellipseTF_:TransformPoint(nearPosLS)
        return nearPosWS, false
    end
end




---@return UnityEngine.Vector3 | nil, boolean @(1) ray 在 椭圆边线上 最近的点 posws; (2) 这个点是否在 弧线内部
function IdolLive3D_UtilsV2.FindClosestPosOnArc( ellipseTF_, ray_, radiusX_, radiusZ_, aPosLS_, bPosLS_ )

    -- Step 1:  
    local ellipsePlane = Plane(ellipseTF_.up, ellipseTF_.position) 
    local isHit, enter = ellipsePlane:Raycast(ray_)
    if isHit == false then    
        print("未找到 ray 和 可活动平面的 交点")
        return nil, false
    end
    local hitPosWS = ray_:GetPoint(enter)  -- ray_ 和椭圆平面的交点
    local hitPosLS = ellipseTF_:InverseTransformPoint(hitPosWS)

    -- Step 2:  
    local zxRatio = radiusZ_ / radiusX_

    local x = hitPosLS.x
    local z = hitPosLS.z  

    local x2 = x
    local z2 = z / zxRatio
    local nearPosLS = Vector3(x2,0,z2).normalized * radiusX_
    nearPosLS.z = nearPosLS.z * zxRatio                         -- 位于椭圆边线上的 最近点
    local nearPosWS = ellipseTF_:TransformPoint(nearPosLS)
    
    -- 
    local a = Vector3.SignedAngle( aPosLS_, nearPosLS, ellipseTF_.up )
    local b = Vector3.SignedAngle( bPosLS_, nearPosLS, ellipseTF_.up )
    local isInside = a >= 0.0 and b <= 0.0
    if isInside  then        
        return nearPosWS, true
    else
        return nearPosWS, false  -- 此时 nearPosWS 在椭圆边线上, 但是在 弧线之外
    end
end





return IdolLive3D_UtilsV2

